<?php
declare(strict_types=1);
require_once __DIR__.'/../standalone/bootstrap.php';require_once __DIR__.'/../autoloader.php';require_once __DIR__.'/../Repository/ConfigManagerRepository.php';require_once __DIR__.'/../Service/ConfigManagerService.php';require_once __DIR__.'/../Controller/ConfigManagerController.php';require_once __DIR__.'/../lib/config_manager_runtime.php';
if(!mmbb_has_service('ConfigManager')){http_response_code(403);echo'Forbidden';exit;} use ConfigManager\Repository\ConfigManagerRepository;use ConfigManager\Service\ConfigManagerService;use ConfigManager\Controller\ConfigManagerController;
if(session_status()===PHP_SESSION_NONE)session_start();if(empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32));$csrf=(string)$_SESSION['csrf_token'];
function fm_json(array$x,int$s=200):never{http_response_code($s);header('Content-Type: application/json; charset=utf-8');header('Cache-Control:no-store');echo json_encode($x,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}function fm_servers():array{return cm_load_config_manager_servers(__DIR__.'/../config/config.php');}function fm_find(array$ss,string$n):array{foreach($ss as$s)if(strcasecmp((string)($s['name']??''),$n)===0)return$s;throw new RuntimeException('Unbekannter Server.',404);}function fm_ctl(array$s):ConfigManagerController{return new ConfigManagerController(new ConfigManagerService(new ConfigManagerRepository($s)));}function fm_body():array{$x=json_decode((string)file_get_contents('php://input'),true);if(!is_array($x))throw new RuntimeException('Ungültiges JSON.',400);return$x;}function fm_unwrap(array$r):array{$c=(int)($r['http_code']??500);$x=is_array($r['response']??null)?$r['response']:[];if($c<200||$c>=300||empty($x['ok']))throw new RuntimeException((string)($x['error']??('Agent HTTP '.$c)),$c>=400&&$c<=599?$c:502);return$x;}
try{$ss=fm_servers();$api=(string)($_GET['api']??'');if($api==='summary')fm_json(['ok'=>true,'servers'=>array_map(fn($s)=>['name'=>(string)($s['name']??'')],$ss)]);if(in_array($api,['roots','list','read'],true)){$s=fm_find($ss,trim((string)($_GET['server']??'')));$c=fm_ctl($s);if($api==='roots')fm_json(['ok'=>true,'data'=>fm_unwrap($c->getFileManagerRoots())]);if($api==='list')fm_json(['ok'=>true,'data'=>fm_unwrap($c->listManagedFiles((string)($_GET['path']??'')))]);if($api==='read')fm_json(['ok'=>true,'data'=>fm_unwrap($c->readManagedFile((string)($_GET['path']??'')))]);}if($_SERVER['REQUEST_METHOD']==='POST'){$in=fm_body();if(!hash_equals($csrf,(string)($in['csrf_token']??'')))throw new RuntimeException('CSRF fehlgeschlagen.',403);$s=fm_find($ss,trim((string)($in['server_name']??'')));$c=fm_ctl($s);$a=(string)($in['action']??'');if($a==='write'){$f=(array)($in['file']??[]);$f['override_managed']=!empty($in['override_managed']);fm_json(['ok'=>true,'data'=>fm_unwrap($c->writeManagedFile($f))]);}if($a==='delete')fm_json(['ok'=>true,'data'=>fm_unwrap($c->deleteManagedFile((string)($in['path']??''),!empty($in['override_managed'])))]);if($a==='rename')fm_json(['ok'=>true,'data'=>fm_unwrap($c->renameManagedFile((string)($in['source']??''),(string)($in['target']??''),!empty($in['override_managed'])))]);throw new RuntimeException('Unbekannte Aktion.',400);}}catch(Throwable$e){$c=(int)$e->getCode();fm_json(['ok'=>false,'error'=>$e->getMessage()],$c>=400&&$c<=599?$c:500);}
?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Datei Manager</title><?php require MMBB_UI.'/includes/css.php';?>
<style>
.fm-shell{display:grid;grid-template-columns:minmax(340px,42%) 1fr;gap:1rem;min-height:680px}.fm-browser,.fm-editor-card{min-width:0}.fm-toolbar{display:flex;gap:.45rem;align-items:center;flex-wrap:wrap}.fm-path{font-family:ui-monospace,SFMono-Regular,Menlo,monospace}.fm-breadcrumb{display:flex;align-items:center;gap:.25rem;flex-wrap:wrap;font-size:.86rem}.fm-crumb{border:0;background:transparent;color:var(--bs-primary);padding:.12rem .2rem}.fm-crumb:hover{text-decoration:underline}.fm-list-head,.fm-entry{display:grid;grid-template-columns:minmax(0,1fr) 82px 86px;align-items:center;gap:.5rem}.fm-list-head{font-size:.72rem;font-weight:700;text-transform:uppercase;color:var(--bs-secondary-color);padding:.55rem .75rem;border-bottom:1px solid var(--bs-border-color)}.fm-list{max-height:565px;overflow:auto}.fm-entry{padding:.56rem .75rem;border-bottom:1px solid var(--bs-border-color);cursor:pointer}.fm-entry:hover,.fm-entry.active{background:var(--bs-tertiary-bg)}.fm-name{display:flex;align-items:center;gap:.55rem;min-width:0}.fm-name strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.fm-meta{font-size:.78rem;color:var(--bs-secondary-color)}.fm-icon{width:1.4rem;text-align:center;font-size:1.05rem}.fm-folder .fm-icon{color:#d89b15}.fm-file .fm-icon{color:var(--bs-primary)}.fm-empty{padding:2rem 1rem;text-align:center;color:var(--bs-secondary-color)}.fm-editor-head{display:flex;align-items:center;gap:.6rem;min-width:0}.fm-current-wrap{min-width:0;flex:1}.fm-current-name{font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.fm-current-path{font-size:.78rem;color:var(--bs-secondary-color);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.fm-editor-toolbar{display:flex;gap:.45rem;align-items:center;flex-wrap:wrap}.fm-mode{width:92px}.fm-editor-wrap{position:relative}.fm-editor{width:100%;min-height:535px;resize:vertical;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.9rem;line-height:1.45;border-radius:.45rem}.fm-statusbar{display:flex;justify-content:space-between;gap:1rem;font-size:.76rem;color:var(--bs-secondary-color);padding-top:.45rem}.fm-scope-chip{display:inline-flex;align-items:center;gap:.35rem;border:1px solid var(--bs-border-color);border-radius:999px;padding:.18rem .55rem;margin:.12rem .15rem .12rem 0;background:var(--bs-body-bg);font-size:.76rem}.fm-readonly{background:var(--bs-tertiary-bg);border-left:3px solid var(--bs-warning)}.fm-search{max-width:220px}.fm-card-header{min-height:52px}.modal-path{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.83rem;overflow-wrap:anywhere}@media(max-width:1100px){.fm-shell{grid-template-columns:1fr}.fm-list{max-height:400px}.fm-editor{min-height:430px}}@media(max-width:650px){.fm-list-head,.fm-entry{grid-template-columns:minmax(0,1fr) 66px}.fm-list-head>*:nth-child(3),.fm-entry>*:nth-child(3){display:none}}
</style></head><body><?php require __DIR__.'/../standalone/layout/sidebar.php';?><main class="main-content"><div class="container-fluid py-3"><?php $moduleHeaderTitle='Datei Manager';$moduleHeaderSubtitle='Moderner Host-Dateibrowser mit Pfadnavigation, Verlauf und kontrolliertem Editor. Schreibrechte werden weiterhin serverseitig vom Config Agent erzwungen.';$moduleHeaderIcon='bi bi-folder2-open';require __DIR__.'/../standalone/layout/module_header.php';?>
<div id="msg"></div>
<div class="card mb-3"><div class="card-body"><div class="row g-2 align-items-end"><div class="col-lg-3"><label class="form-label small fw-semibold">Zielserver</label><select id="server" class="form-select"></select></div><div class="col-lg-6"><label class="form-label small fw-semibold">Pfad</label><div class="input-group"><button id="back" class="btn btn-outline-secondary" title="Zurück" disabled><i class="bi bi-arrow-left"></i></button><button id="forward" class="btn btn-outline-secondary" title="Vorwärts" disabled><i class="bi bi-arrow-right"></i></button><button id="up" class="btn btn-outline-secondary" title="Eine Ebene höher"><i class="bi bi-arrow-up"></i></button><input id="path" class="form-control fm-path"><button id="open" class="btn btn-primary"><i class="bi bi-box-arrow-in-right me-1"></i>Öffnen</button></div></div><div class="col-lg-3"><label class="form-label small fw-semibold">Startpunkt</label><select id="root" class="form-select"></select></div></div><div id="crumbs" class="fm-breadcrumb mt-3"></div></div></div>
<div id="scopeInfo" class="card mb-3 d-none"><div class="card-body py-2"><div class="d-flex flex-wrap align-items-center gap-2"><strong class="me-2">Zugriff</strong><span id="readScopes"></span><span class="vr"></span><span id="writeScopes"></span></div><div id="hiddenNotice" class="small text-body-secondary mt-1 d-none"></div><div id="blockedScopes" class="small text-body-secondary mt-1"></div></div></div>
<div class="fm-shell"><section class="card fm-browser"><div class="card-header fm-card-header d-flex align-items-center gap-2"><strong><i class="bi bi-folder2-open me-2"></i>Verzeichnis</strong><div class="ms-auto d-flex gap-2"><input id="filter" class="form-control form-control-sm fm-search" placeholder="Dateien filtern …"><button id="refresh" class="btn btn-sm btn-outline-secondary" title="Aktualisieren"><i class="bi bi-arrow-clockwise"></i></button><button id="newFile" class="btn btn-sm btn-primary"><i class="bi bi-file-earmark-plus me-1"></i>Neue Datei</button></div></div><div class="fm-list-head"><div>Name</div><div>Modus</div><div>Grösse</div></div><div class="fm-list" id="files"></div></section>
<section class="card fm-editor-card"><div class="card-header fm-card-header"><div class="fm-editor-head"><i class="bi bi-file-earmark-code fs-5"></i><div class="fm-current-wrap"><div id="currentName" class="fm-current-name">Keine Datei ausgewählt</div><div id="currentPath" class="fm-current-path">Datei im Browser auswählen oder neu erstellen.</div></div><div class="fm-editor-toolbar"><span id="dirtyBadge" class="badge text-bg-warning d-none">ungespeichert</span><select id="mode" class="form-select form-select-sm fm-mode" disabled><option>0600</option><option selected>0640</option><option>0644</option><option>0660</option><option>0750</option><option>0755</option></select><button id="rename" class="btn btn-sm btn-outline-secondary" disabled><i class="bi bi-pencil-square me-1"></i>Umbenennen</button><button id="delete" class="btn btn-sm btn-outline-danger" disabled><i class="bi bi-trash me-1"></i>Löschen</button><button id="save" class="btn btn-sm btn-success" disabled><i class="bi bi-save me-1"></i>Speichern</button></div></div></div><div class="card-body"><div id="ownership" class="alert alert-warning py-2 d-none"></div><div id="readOnlyInfo" class="alert alert-secondary py-2 d-none"></div><div class="fm-editor-wrap"><textarea id="editor" class="form-control fm-editor" spellcheck="false" disabled placeholder="Dateiinhalt …"></textarea></div><div class="fm-statusbar"><span id="editorStats">0 Zeilen · 0 Zeichen</span><span>Max. 1 MiB · Backups vor Änderungen · Symlinks/Secrets serverseitig geschützt</span></div></div></section></div>
</div></main>
<div class="modal fade" id="fmModal" tabindex="-1" aria-hidden="true"><div class="modal-dialog"><div class="modal-content"><div class="modal-header"><h5 class="modal-title" id="modalTitle">Aktion</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div id="modalText" class="mb-3"></div><label id="modalLabel" class="form-label fw-semibold d-none"></label><input id="modalInput" class="form-control fm-path d-none"><div id="modalExtra" class="small text-body-secondary mt-2"></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Abbrechen</button><button type="button" id="modalConfirm" class="btn btn-primary">Bestätigen</button></div></div></div></div>
<?php require MMBB_UI.'/includes/js.php';?><script>
const CSRF=<?=json_encode($csrf)?>,$=id=>document.getElementById(id);let CUR='',OWN={managed:false},BASE_CONTENT='',ENTRIES=[],HISTORY=[],HIDX=-1,READ_ROOTS=[],WRITE_ROOTS=[];const modal=new bootstrap.Modal($('fmModal'));function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function msg(t,type='info'){$('msg').innerHTML=`<div class="alert alert-${type} py-2">${esc(t)}</div>`}async function api(u,o={}){const r=await fetch(u,{cache:'no-store',...o}),j=await r.json().catch(()=>({ok:false,error:'Ungültige Antwort'}));if(!r.ok||j.ok===false)throw new Error(j.error||`HTTP ${r.status}`);return j}function qs(o){return new URLSearchParams(o).toString()}function norm(p){p=String(p||'/').replace(/\/+/g,'/');if(!p.startsWith('/'))p='/'+p;return p.length>1?p.replace(/\/$/,''):p}function dirname(p){p=norm(p);if(p==='/')return '/';const x=p.split('/');x.pop();return x.join('/')||'/'}function basename(p){p=norm(p);return p==='/'?'/':p.split('/').pop()}function fmtSize(n){n=Number(n||0);if(n<1024)return n+' B';if(n<1048576)return (n/1024).toFixed(1)+' KiB';return (n/1048576).toFixed(1)+' MiB'}function canWritePath(p){p=norm(p);return WRITE_ROOTS.some(r=>p===norm(r)||p.startsWith(norm(r).replace(/\/$/,'')+'/'))}function updateNav(){ $('back').disabled=HIDX<=0;$('forward').disabled=HIDX<0||HIDX>=HISTORY.length-1;$('up').disabled=norm($('path').value)==='/'}function pushHistory(p){p=norm(p);if(HIDX>=0&&HISTORY[HIDX]===p)return;HISTORY=HISTORY.slice(0,HIDX+1);HISTORY.push(p);HIDX=HISTORY.length-1;updateNav()}function renderCrumbs(){const p=norm($('path').value),parts=p.split('/').filter(Boolean);let acc='';let h='<button class="fm-crumb" data-path="/"><i class="bi bi-hdd-rack me-1"></i>/</button>';for(const part of parts){acc+='/'+part;h+='<span class="text-body-secondary">/</span><button class="fm-crumb" data-path="'+esc(acc)+'">'+esc(part)+'</button>'}$('crumbs').innerHTML=h;document.querySelectorAll('.fm-crumb').forEach(b=>b.onclick=()=>navigate(b.dataset.path))}function stats(){const v=$('editor').value;$('editorStats').textContent=(v?v.split('\n').length:0)+' Zeilen · '+v.length+' Zeichen';const dirty=v!==BASE_CONTENT;$('dirtyBadge').classList.toggle('d-none',!dirty)}function setWriteState(){const writable=CUR&&canWritePath(CUR);$('editor').disabled=!CUR||!writable;$('mode').disabled=!CUR||!writable;$('save').disabled=!CUR||!writable;$('rename').disabled=!CUR||!writable;$('delete').disabled=!CUR||!writable;const ro=$('readOnlyInfo');if(CUR&&!writable){ro.classList.remove('d-none');ro.innerHTML='<i class="bi bi-eye me-1"></i><strong>Nur lesen:</strong> Dieser Pfad liegt ausserhalb der freigegebenen Schreibbereiche des Config Agents.'}else{ro.classList.add('d-none');ro.textContent=''}}
async function roots(){try{const j=await api('file_manager.php?'+qs({api:'roots',server:$('server').value}));READ_ROOTS=j.data.read_roots||j.data.roots||[];WRITE_ROOTS=j.data.write_roots||[];const bs=j.data.runtime_blocked||[];$('root').innerHTML=READ_ROOTS.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');$('readScopes').innerHTML='<span class="text-body-secondary me-1">Lesen</span>'+READ_ROOTS.map(x=>`<span class="fm-scope-chip"><i class="bi bi-eye"></i>${esc(x)}</span>`).join('');$('writeScopes').innerHTML='<span class="text-body-secondary me-1">Schreiben</span>'+(WRITE_ROOTS.length?WRITE_ROOTS.map(x=>`<span class="fm-scope-chip"><i class="bi bi-pencil"></i>${esc(x)}</span>`).join(''):'<span class="badge text-bg-secondary">keine Schreibfreigabe</span>');$('blockedScopes').textContent=bs.length?'Ausgeschlossen: '+bs.join(', '):'';$('scopeInfo').classList.remove('d-none');HISTORY=[];HIDX=-1;CUR='';clearEditor();if(READ_ROOTS.length)await navigate(READ_ROOTS[0],true)}catch(e){msg(e.message,'danger')}}
async function navigate(p,add=true){p=norm(p);$('path').value=p;if(add)pushHistory(p);renderCrumbs();updateNav();await list()}async function list(){try{const j=await api('file_manager.php?'+qs({api:'list',server:$('server').value,path:norm($('path').value)}));ENTRIES=(j.data.entries||[]).slice().sort((a,b)=>(a.type==='dir'?0:1)-(b.type==='dir'?0:1)||String(a.name).localeCompare(String(b.name),'de'));const hn=Number(j.data.hidden_protected||0);const h=$('hiddenNotice');if(h){h.classList.toggle('d-none',hn<1);h.innerHTML=hn?'<i class="bi bi-shield-lock me-1"></i>'+hn+' geschützte Systemeinträge werden bewusst nicht angezeigt.':''}renderList();renderCrumbs();updateNav()}catch(e){msg(e.message,'danger')}}function renderList(){const q=$('filter').value.trim().toLowerCase(),xs=ENTRIES.filter(e=>!q||String(e.name).toLowerCase().includes(q));$('files').innerHTML=xs.length?xs.map(e=>`<div class="fm-entry ${e.type==='dir'?'fm-folder':'fm-file'} ${CUR===e.path?'active':''}" data-path="${esc(e.path)}" data-type="${esc(e.type)}"><div class="fm-name"><i class="fm-icon bi ${e.type==='dir'?'bi-folder-fill':'bi-file-earmark-text'}"></i><div class="min-width-0"><strong title="${esc(e.name)}">${esc(e.name)}</strong>${e.ownership?.managed?'<span class="badge text-bg-warning ms-2">verwaltet</span>':''}<div class="fm-meta">${e.type==='dir'?'Ordner':'Datei'}</div></div></div><div class="fm-meta">${esc(e.mode||'—')}</div><div class="fm-meta">${e.type==='dir'?'—':fmtSize(e.size)}</div></div>`).join(''):'<div class="fm-empty"><i class="bi bi-folder2-open fs-2 d-block mb-2"></i>Keine Einträge.</div>';document.querySelectorAll('.fm-entry').forEach(x=>x.onclick=()=>x.dataset.type==='dir'?navigate(x.dataset.path):read(x.dataset.path))}
function clearEditor(){CUR='';OWN={managed:false};BASE_CONTENT='';$('currentName').textContent='Keine Datei ausgewählt';$('currentPath').textContent='Datei im Browser auswählen oder neu erstellen.';$('editor').value='';$('mode').value='0640';$('ownership').classList.add('d-none');$('readOnlyInfo').classList.add('d-none');setWriteState();stats();renderList()}async function read(p){try{const j=await api('file_manager.php?'+qs({api:'read',server:$('server').value,path:p}));CUR=p;OWN=j.data.ownership||{managed:false};BASE_CONTENT=j.data.content||'';$('currentName').textContent=basename(p);$('currentPath').textContent=p;$('editor').value=BASE_CONTENT;$('mode').value=j.data.mode||'0640';const ow=$('ownership');if(OWN.managed){ow.classList.remove('d-none');ow.innerHTML='<i class="bi bi-shield-lock me-1"></i><strong>Verwaltet durch '+esc(OWN.source||OWN.owner)+'</strong><br>'+esc(OWN.message||'Diese Datei wird zentral verwaltet.')+'<br><small>Direkte Änderungen benötigen einen bewussten Expert-Override und können beim nächsten Deployment überschrieben werden.</small>'}else{ow.classList.add('d-none');ow.textContent=''};setWriteState();stats();renderList()}catch(e){msg(e.message,'danger')}}async function post(o){return api('file_manager.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf_token:CSRF,server_name:$('server').value,...o})})}
function ask({title,text='',label='',value='',confirm='Bestätigen',danger=false,extra=''},cb){$('modalTitle').textContent=title;$('modalText').innerHTML=text;$('modalLabel').textContent=label;$('modalLabel').classList.toggle('d-none',!label);$('modalInput').classList.toggle('d-none',!label);$('modalInput').value=value;$('modalExtra').textContent=extra;$('modalConfirm').textContent=confirm;$('modalConfirm').className='btn '+(danger?'btn-danger':'btn-primary');$('modalConfirm').onclick=async()=>{await cb($('modalInput').value);modal.hide()};modal.show();setTimeout(()=>{if(label)$('modalInput').focus()},250)}
async function init(){try{const j=await api('file_manager.php?api=summary');$('server').innerHTML=(j.servers||[]).map(s=>`<option>${esc(s.name)}</option>`).join('');if(j.servers?.length)await roots()}catch(e){msg(e.message,'danger')}}
$('server').onchange=roots;$('root').onchange=()=>navigate($('root').value);$('open').onclick=()=>navigate($('path').value);$('path').onkeydown=e=>{if(e.key==='Enter')navigate($('path').value)};$('refresh').onclick=list;$('filter').oninput=renderList;$('up').onclick=()=>navigate(dirname($('path').value));$('back').onclick=async()=>{if(HIDX>0){HIDX--;await navigate(HISTORY[HIDX],false)}};$('forward').onclick=async()=>{if(HIDX<HISTORY.length-1){HIDX++;await navigate(HISTORY[HIDX],false)}};$('editor').oninput=stats;
$('newFile').onclick=()=>{if(!canWritePath($('path').value)){msg('Dieser Ordner ist nur lesbar. Für das Erstellen einer Datei ist eine Schreibfreigabe im Config Agent erforderlich.','warning');return}ask({title:'Neue Datei',text:'Die Datei wird im aktuellen Verzeichnis angelegt.',label:'Dateiname',value:'',confirm:'Datei anlegen'},async n=>{n=n.trim();if(!/^[A-Za-z0-9_.-]{1,128}$/.test(n))throw new Error('Ungültiger Dateiname.');CUR=norm($('path').value)+'/'+n;OWN={managed:false};BASE_CONTENT='';$('currentName').textContent=n;$('currentPath').textContent=CUR;$('editor').value='';$('mode').value='0640';$('ownership').classList.add('d-none');setWriteState();stats();$('editor').focus()})};
async function saveFile(override=false){try{await post({action:'write',override_managed:override,file:{path:CUR,content:$('editor').value,mode:$('mode').value}});BASE_CONTENT=$('editor').value;stats();msg('Datei gespeichert und Backup angelegt.','success');await list();await read(CUR)}catch(e){msg(e.message,'danger')}}$('save').onclick=()=>{if(OWN.managed){ask({title:'Expert-Override',text:'<div class="alert alert-warning mb-0">Diese Datei wird zentral verwaltet. Eine direkte Änderung kann beim nächsten Deployment überschrieben werden.</div>',confirm:'Trotzdem speichern',danger:true},async()=>saveFile(true));return}saveFile(false)};
$('delete').onclick=()=>{if(!CUR)return;ask({title:'Datei löschen',text:`<div class="modal-path">${esc(CUR)}</div>`,confirm:'Endgültig löschen',danger:true,extra:'Vor dem Löschen wird serverseitig ein Backup angelegt.'},async()=>{try{let override=!!OWN.managed;await post({action:'delete',path:CUR,override_managed:override});clearEditor();msg('Datei gelöscht.','success');await list()}catch(e){msg(e.message,'danger')}})};$('rename').onclick=()=>{if(!CUR)return;ask({title:'Datei umbenennen',text:`Aktuell: <span class="modal-path">${esc(CUR)}</span>`,label:'Neuer vollständiger Pfad',value:CUR,confirm:'Umbenennen'},async n=>{n=n.trim();if(!n||n===CUR)return;try{await post({action:'rename',source:CUR,target:n,override_managed:!!OWN.managed});CUR=n;msg('Datei umbenannt.','success');await list();await read(CUR)}catch(e){msg(e.message,'danger')}})};init();
</script></body></html>